def unique_tags(tags):
    """去除重复标签，保留首次出现顺序。"""
    return list(set(tags))

verification_tests:
from target import unique_tags

def test_no_dupes_content():
    r = unique_tags(["a", "b"])
    assert set(r) == {"a", "b"} and len(r) == 2

def test_empty():
    assert unique_tags([]) == []

def test_order():
    assert unique_tags([2, 1, 2, 3, 1]) == [2, 1, 3]
